BEGIN; DO $$
DECLARE prod uuid:=gen_random_uuid(); cat uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); lines jsonb; rules jsonb; out jsonb; fx jsonb:='{"BRL":1,"USD":0.2,"PYG":1400}';
BEGIN
 lines:=jsonb_build_array(jsonb_build_object('item_id',a,'product_id',prod,'category_id',cat,'total',100,'commission_enabled',true,'commission_percent',5,'commission_amount',5),jsonb_build_object('item_id',b,'product_id',prod,'category_id',cat,'total',100,'commission_enabled',true,'commission_percent',5,'commission_amount',5),jsonb_build_object('item_id',c,'product_id',prod,'category_id',cat,'total',100,'commission_enabled',true,'commission_percent',5,'commission_amount',5));
 rules:=jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'comp_type','percent','amount',20,'currency','BRL'),jsonb_build_object('id',gen_random_uuid(),'product_id',prod,'comp_type','percent','amount',15,'currency','BRL'),jsonb_build_object('id',gen_random_uuid(),'category_id',cat,'comp_type','percent','amount',10,'currency','BRL'),jsonb_build_object('id',gen_random_uuid(),'item_id',a,'comp_type','percent','amount',7,'currency','BRL'));
 out:=private.integral_calculate_commission_rules(lines,fx,rules);
 IF (out->>'commission_total')::numeric<>27 OR (out->'items'->0->>'commission_amount')::numeric<>7 THEN RAISE EXCEPTION 'Specific priority failed: %',out; END IF;
 out:=private.integral_calculate_commission_rules(lines,fx,'[]'::jsonb);
 IF (out->>'commission_total')::numeric<>15 THEN RAISE EXCEPTION 'Catalog fallback changed'; END IF;
 rules:=jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'product_id',prod,'comp_type','fixed','amount',1,'currency','USD'));
 out:=private.integral_calculate_commission_rules(lines,fx,rules);
 IF (out->>'commission_total')::numeric<>5 OR (out->'items'->2->>'commission_amount')::numeric<>1.68 THEN RAISE EXCEPTION 'Fixed once/conversion/rounding failed: %',out; END IF;
 rules:=rules||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'item_id',a,'comp_type','percent','amount',7,'currency','BRL'));
 out:=private.integral_calculate_commission_rules(lines,fx,rules);
 IF (out->>'commission_total')::numeric<>12 OR (out->'items'->0->>'commission_amount')::numeric<>7 THEN RAISE EXCEPTION 'Specific agreement did not replace fixed category: %',out; END IF;
END $$; SELECT 'Specific priority, fallback, fixed per sale, conversion and cent allocation passed' result; ROLLBACK;
-- policy_create_order_test_sql
BEGIN; DO $$ DECLARE actor uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); wh uuid:=gen_random_uuid(); request jsonb; quote jsonb; first_sale jsonb; second_sale jsonb; rid uuid:=gen_random_uuid(); BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(actor,'integral-create-test-'||actor||'@example.invalid','{}',now()); PERFORM set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.user_roles WHERE role='superadmin' LIMIT 1),true); INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Controlled sale category',true,true); INSERT INTO public.inventory_items(id,product_id,name,unit,currency,cost,price,quantity,reserved,is_active,is_demo) VALUES(item,prod,'Controlled sale item','UN','BRL',10,100,10,0,true,true); INSERT INTO public.warehouses(id,name,city,state,is_active) VALUES(wh,'Controlled sale warehouse','Test city','SP',true); INSERT INTO public.warehouse_inventory(warehouse_id,item_id,quantity,reserved) VALUES(wh,item,10,0); INSERT INTO public.product_users(user_id,product_id) VALUES(actor,prod); INSERT INTO public.member_compensations(user_id,product_id,comp_type,amount,currency,period) VALUES(actor,prod,'percent',10,'BRL','per_sale'),(actor,prod,'percent',40,'BRL','month'); INSERT INTO public.member_compensations(user_id,item_id,comp_type,amount,currency,period) VALUES(actor,item,'percent',7,'BRL','per_sale'); PERFORM set_config('request.jwt.claim.sub',actor::text,true); request:=jsonb_build_object('currency','BRL','exchange',jsonb_build_object('mode','automatic'),'warehouse_id',wh,'destination',jsonb_build_object('country','Brasil','state','SP','city','Test city','address','Test address','number','1','recipient_name','Controlled customer','phone','12345'),'customer',jsonb_build_object('name','Controlled customer','phone','12345'),'items',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2,'discount_percent',0)),'notes','Controlled create'); quote:=public.seller_portal_quote(request); IF (quote->>'commission_total')::numeric<>14 THEN RAISE EXCEPTION 'Quote ignored item priority: %',quote; END IF; first_sale:=public.integral_seller_create_order(request,rid,quote,NULL); second_sale:=public.integral_seller_create_order(request,rid,quote,NULL); IF first_sale->>'id' IS DISTINCT FROM second_sale->>'id' OR (SELECT count(*) FROM public.orders WHERE seller_id=actor)<>1 THEN RAISE EXCEPTION 'Sale idempotency failed'; END IF; IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=(first_sale->>'id')::uuid AND seller_id=actor AND customer_id IS NOT NULL AND warehouse_id=wh) THEN RAISE EXCEPTION 'Sale customer linkage failed'; END IF; IF (SELECT commission_total FROM public.orders WHERE id=(first_sale->>'id')::uuid)<>14 THEN RAISE EXCEPTION 'Persisted commission mismatch'; END IF;
 IF (SELECT jsonb_array_length(rules) FROM private.integral_order_compensation_rules WHERE order_id=(first_sale->>'id')::uuid)<>2 THEN RAISE EXCEPTION 'Monthly agreement captured as sale commission'; END IF;
 PERFORM set_config('request.jwt.claim.sub','',true);
 UPDATE public.member_compensations SET amount=50 WHERE user_id=actor AND item_id=item;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 quote:=public.seller_portal_quote(request);
 IF (quote->>'commission_total')::numeric<>100 THEN RAISE EXCEPTION 'Future quote did not use changed agreement'; END IF;
 INSERT INTO private.seller_creation_context VALUES(pg_backend_pid(),txid_current(),actor,(first_sale->>'id')::uuid,'edit_order');
 PERFORM private.integral_apply_order_compensation((first_sale->>'id')::uuid);
 DELETE FROM private.seller_creation_context WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND new_order_id=(first_sale->>'id')::uuid;
 IF (SELECT commission_total FROM public.orders WHERE id=(first_sale->>'id')::uuid)<>14 THEN RAISE EXCEPTION 'Existing commission changed retroactively'; END IF;
 PERFORM public.integral_register_payment((first_sale->>'id')::uuid,gen_random_uuid(),jsonb_build_object('received_amount',40,'method','dinheiro','paid_at',current_date));
 PERFORM set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.user_roles WHERE role='superadmin' LIMIT 1),true);
 PERFORM public.finance_confirm_seller_payment((SELECT id FROM public.payments WHERE order_id=(first_sale->>'id')::uuid AND status='pendente' LIMIT 1));
 IF (SELECT amount_paid FROM public.orders WHERE id=(first_sale->>'id')::uuid)<>40 OR (SELECT commission_total FROM public.orders WHERE id=(first_sale->>'id')::uuid)<>14 THEN RAISE EXCEPTION 'Partial payment changed commission or balance'; END IF;
 IF abs((SELECT quantity FROM public.warehouse_inventory WHERE warehouse_id=wh AND item_id=item)-(10-2*40/(SELECT total FROM public.orders WHERE id=(first_sale->>'id')::uuid)))>0.001 OR abs((SELECT reserved FROM public.warehouse_inventory WHERE warehouse_id=wh AND item_id=item)-(2-2*40/(SELECT total FROM public.orders WHERE id=(first_sale->>'id')::uuid)))>0.001 THEN RAISE EXCEPTION 'Partial stock mismatch: total %, qty %, reserved %',(SELECT total FROM public.orders WHERE id=(first_sale->>'id')::uuid),(SELECT quantity FROM public.warehouse_inventory WHERE warehouse_id=wh AND item_id=item),(SELECT reserved FROM public.warehouse_inventory WHERE warehouse_id=wh AND item_id=item); END IF;
 END $$; ROLLBACK;


-- policy_seller_edit_test_sql
BEGIN; DO $$ DECLARE actor uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); wh uuid:=gen_random_uuid(); args jsonb; followup jsonb; result jsonb; BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(actor,'integral-edit-test-'||actor||'@example.invalid','{}',now());  PERFORM set_config('request.jwt.claim.sub',(SELECT user_id::text FROM public.user_roles WHERE role='superadmin' LIMIT 1),true); INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Controlled policy test',true,true); INSERT INTO public.inventory_items(id,product_id,name,unit,currency,cost,price,quantity,reserved,is_active,is_demo) VALUES(item,prod,'Controlled item','UN','BRL',10,100,10,0,true,true); INSERT INTO public.warehouses(id,name,city,state,is_active) VALUES(wh,'Controlled warehouse','Controlled city','SP',true); INSERT INTO public.warehouse_inventory(warehouse_id,item_id,quantity,reserved) VALUES(wh,item,9,0); INSERT INTO public.member_compensations(user_id,item_id,comp_type,amount,currency,period) VALUES(actor,item,'percent',7,'BRL','per_sale'); INSERT INTO public.orders(id,number,seller_id,product_id,warehouse_id,currency,total,amount_paid,amount_receivable,status,kind,stock_state,workflow_stage,order_date,exchange_rates_snapshot,exchange_rate_locked_at,is_demo) VALUES(oid,-2147480002,actor,prod,wh,'BRL',100,0,100,'faturado','venda','baixado','pedido_feito',current_date,jsonb_build_object('base','BRL','BRL',1,'USD',0.2,'PYG',1400),now(),true); INSERT INTO public.order_items(order_id,item_id,description,unit,quantity,unit_price,discount,total) VALUES(oid,item,'Controlled item','UN',1,100,0,100); args:=jsonb_build_object('p_previous_order_id',oid,'p_customer_id',null,'p_product_id',prod,'p_currency','BRL','p_discount',0,'p_shipping_cost',0,'p_shipping_percentage',null,'p_notes','Controlled edit','p_whatsapp',null,'p_items',jsonb_build_array(jsonb_build_object('item_id',item,'description','Controlled item','unit','UN','quantity',2,'unit_price',100,'discount',0)),'p_warehouse_id',wh,'p_shipping_address','Test address','p_shipping_city','Test city','p_shipping_state','SP','p_delivery_deadline',null,'p_carrier','','p_tracking_code',''); followup:=jsonb_build_object('delivery_recipient_name','Controlled','delivery_recipient_document','','shipping_cep','','variable_cost',0,'seller_id',actor,'order_date',current_date,'delivery_deadline',null,'delivered_at',null,'shipping_country','Brasil','shipping_address_number','1'); PERFORM private.integral_apply_order_compensation(oid);
 result:=public.integral_preview_order_commission(actor,jsonb_build_object('base','BRL','BRL',1,'USD',0.2,'PYG',1400),jsonb_build_array(jsonb_build_object('item_id',item,'description','Controlled item','total',200,'commission_percent',0,'commission_amount',0)),NULL);
 IF (result->>'commission_total')::numeric<>14 THEN RAISE EXCEPTION 'Admin preview did not use seller agreement'; END IF;
 UPDATE public.member_compensations SET amount=50 WHERE user_id=actor AND item_id=item; INSERT INTO public.product_users(user_id,product_id) VALUES(actor,prod); PERFORM set_config('request.jwt.claim.sub',actor::text,true); result:=public.integral_submit_order_edit(args,followup,null,'Controlled quantity update',gen_random_uuid()); IF result->>'id' IS NULL OR (SELECT count(*) FROM public.orders WHERE root_order_id=oid AND superseded_at IS NULL)<>1 THEN RAISE EXCEPTION 'Order revision test failed'; END IF; IF (SELECT commission_total FROM public.orders WHERE id=(result->>'id')::uuid)<>14 OR (SELECT commission_total FROM public.orders WHERE id=oid)<>7 THEN RAISE EXCEPTION 'Revision lost frozen agreement'; END IF; 
 PERFORM set_config('request.jwt.claim.sub','',true);
 BEGIN
 PERFORM public.integral_preview_order_commission(actor,jsonb_build_object('base','BRL','BRL',1,'USD',0.2,'PYG',1400),'[]'::jsonb,NULL);
 RAISE EXCEPTION 'Anonymous preview unexpectedly allowed';
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 DELETE FROM private.integral_order_compensation_rules WHERE order_id=(result->>'id')::uuid;
 UPDATE public.orders SET commission_total=3 WHERE id=(result->>'id')::uuid;
 PERFORM private.integral_apply_order_compensation((result->>'id')::uuid);
 IF (SELECT commission_total FROM public.orders WHERE id=(result->>'id')::uuid)<>3 THEN RAISE EXCEPTION 'Historical order without snapshot was repriced'; END IF;
END $$; ROLLBACK;

